//! Fensterloser Screenshot: egui-Frames ohne GPU tessellieren und per CPU rastern.
use std::collections::HashMap;

use egui::epaint::{ClippedPrimitive, ImageData, Primitive, TextureId};
use egui::{Color32, Pos2, RawInput, Rect, Vec2, ViewportId, ViewportInfo};

use crate::app::App;

struct Tex {
    w: usize,
    h: usize,
    px: Vec<Color32>,
}

fn apply(textures: &mut HashMap<TextureId, Tex>, delta: &mut egui::TexturesDelta) {
    for (id, list) in std::mem::take(&mut delta.set) {
        for d in list {
            #[allow(unreachable_patterns)]
            let img = match &d.image {
                ImageData::Color(c) => c.clone(),
                _ => continue,
            };
            let [w, h] = img.size;
            match d.pos {
                None => {
                    textures.insert(id, Tex { w, h, px: img.pixels.clone() });
                }
                Some([x0, y0]) => {
                    if let Some(t) = textures.get_mut(&id) {
                        for y in 0..h {
                            for x in 0..w {
                                if x0 + x < t.w && y0 + y < t.h {
                                    t.px[(y0 + y) * t.w + x0 + x] = img.pixels[y * w + x];
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    for id in std::mem::take(&mut delta.free) {
        textures.remove(&id);
    }
}

fn sample(t: &Tex, u: f32, v: f32) -> [f32; 4] {
    let x = (u * t.w as f32 - 0.5).clamp(0.0, (t.w - 1) as f32);
    let y = (v * t.h as f32 - 0.5).clamp(0.0, (t.h - 1) as f32);
    let (x0, y0) = (x.floor() as usize, y.floor() as usize);
    let (x1, y1) = ((x0 + 1).min(t.w - 1), (y0 + 1).min(t.h - 1));
    let (fx, fy) = (x - x0 as f32, y - y0 as f32);
    let g = |xx: usize, yy: usize| t.px[yy * t.w + xx].to_array();
    let (a, b, c, d) = (g(x0, y0), g(x1, y0), g(x0, y1), g(x1, y1));
    let mut o = [0.0; 4];
    for i in 0..4 {
        let top = a[i] as f32 * (1.0 - fx) + b[i] as f32 * fx;
        let bot = c[i] as f32 * (1.0 - fx) + d[i] as f32 * fx;
        o[i] = (top * (1.0 - fy) + bot * fy) / 255.0;
    }
    o
}

fn raster(prims: &[ClippedPrimitive], textures: &HashMap<TextureId, Tex>, ppp: f32, w: usize, h: usize, bg: Color32) -> Vec<[f32; 3]> {
    let bgc = bg.to_array();
    let mut buf = vec![[bgc[0] as f32 / 255.0, bgc[1] as f32 / 255.0, bgc[2] as f32 / 255.0]; w * h];
    for cp in prims {
        let Primitive::Mesh(mesh) = &cp.primitive else { continue };
        let Some(tex) = textures.get(&mesh.texture_id) else { continue };
        let clip = Rect::from_min_max(Pos2::new(cp.clip_rect.min.x * ppp, cp.clip_rect.min.y * ppp), Pos2::new(cp.clip_rect.max.x * ppp, cp.clip_rect.max.y * ppp));
        let cx0 = clip.min.x.max(0.0).floor() as i64;
        let cy0 = clip.min.y.max(0.0).floor() as i64;
        let cx1 = clip.max.x.min(w as f32).ceil() as i64;
        let cy1 = clip.max.y.min(h as f32).ceil() as i64;
        for tri in mesh.indices.chunks_exact(3) {
            let v = [&mesh.vertices[tri[0] as usize], &mesh.vertices[tri[1] as usize], &mesh.vertices[tri[2] as usize]];
            let p: Vec<Vec2> = v.iter().map(|v| v.pos.to_vec2() * ppp).collect();
            let area = (p[1] - p[0]).x * (p[2] - p[0]).y - (p[1] - p[0]).y * (p[2] - p[0]).x;
            if area.abs() < 1e-6 {
                continue;
            }
            let minx = (p.iter().map(|q| q.x).fold(f32::MAX, f32::min).floor() as i64).max(cx0);
            let maxx = (p.iter().map(|q| q.x).fold(f32::MIN, f32::max).ceil() as i64).min(cx1);
            let miny = (p.iter().map(|q| q.y).fold(f32::MAX, f32::min).floor() as i64).max(cy0);
            let maxy = (p.iter().map(|q| q.y).fold(f32::MIN, f32::max).ceil() as i64).min(cy1);
            let cols: Vec<[f32; 4]> = v.iter().map(|v| v.color.to_array().map(|c| c as f32 / 255.0)).collect();
            for y in miny..maxy {
                for x in minx..maxx {
                    let s = Vec2::new(x as f32 + 0.5, y as f32 + 0.5);
                    let e = |a: Vec2, b: Vec2| (b - a).x * (s - a).y - (b - a).y * (s - a).x;
                    let w0 = e(p[1], p[2]) / area;
                    let w1 = e(p[2], p[0]) / area;
                    let w2 = 1.0 - w0 - w1;
                    if w0 < 0.0 || w1 < 0.0 || w2 < 0.0 {
                        continue;
                    }
                    let u = w0 * v[0].uv.x + w1 * v[1].uv.x + w2 * v[2].uv.x;
                    let vv = w0 * v[0].uv.y + w1 * v[1].uv.y + w2 * v[2].uv.y;
                    let t = sample(tex, u, vv);
                    let mut c = [0.0f32; 4];
                    for i in 0..4 {
                        c[i] = (w0 * cols[0][i] + w1 * cols[1][i] + w2 * cols[2][i]) * t[i];
                    }
                    let d = &mut buf[y as usize * w + x as usize];
                    for i in 0..3 {
                        d[i] = c[i] + d[i] * (1.0 - c[3]);
                    }
                }
            }
        }
    }
    buf
}

/// Rendert die App fensterlos und schreibt ein PNG.
/// Zustandsspiegel aller SSH-Backends auffrischen (headless, ohne Fenster).
///
/// Der Screensaver läuft typischerweise, wenn copi **geschlossen** ist. Damit der Spiegel auch
/// dann frisch ist, ruft der Screensaver diesen Modus als kurzen Unterprozess auf: copi liest
/// `backends.json`, richtet fehlende SSH-Backends ein und holt die Live-Zustände nur lesend ab.
///
/// Ausgabe: eine Meldung je Backend auf stdout (leer = nichts zu tun). Fehler eines Backends
/// brechen die übrigen nicht ab – ein toter Server darf den Screensaver nicht aufhalten.
pub fn sync_states() -> Result<String, String> {
    let cfgs = pi_backend::backends::load()?;
    let root = state_mirror_root();
    let mut out = String::new();
    for c in cfgs.iter().filter(|c| c.enabled && c.kind == "ssh") {
        // Kein Prozess starten, keine Sitzung anlegen: nur die eingebettete Einrichtung und der
        // lesende rsync-Abruf. Das ist derselbe Weg, den copi beim Öffnen der Leiste nimmt.
        let be = match c.build() {
            Ok(b) => b,
            Err(e) => {
                out.push_str(&format!("{}: {e}\n", c.label));
                continue;
            }
        };
        match be.fetch_states(&root) {
            Ok(rep) => {
                // Nicht jede leere Antwort ist ein Fehler: ohne laufenden Agenten schreibt die
                // Erweiterung nichts, und ein frisch eingerichteter Server hat noch kein Verzeichnis.
                let mut m = format!("{}: {} Zustandsdateien", c.label, rep.files);
                if !rep.missing.is_empty() {
                    m += &format!(", {} Verzeichnis(se) noch nicht angelegt", rep.missing.len());
                }
                out.push_str(&m);
                out.push('\n');
            }
            Err(e) => out.push_str(&format!("{}: {e}\n", c.label)),
        }
    }
    Ok(out)
}

/// Lokaler Spiegelort der Agentenzustände (`<cache>/copi/agentscope-remote`).
///
/// Muss zu `agentscope.model.MIRROR_ROOT` passen; der Screensaver liest hier. Als Funktion
/// (nicht Konstante), damit Tests und andere Aufrufer ihn mit `COPI_CACHE_DIR` umlenken können.
pub fn state_mirror_root() -> std::path::PathBuf {
    if let Ok(p) = std::env::var("COPI_STATE_MIRROR_DIR") {
        if !p.trim().is_empty() {
            return std::path::PathBuf::from(p);
        }
    }
    pi_backend::copi_cache_dir().unwrap_or_else(std::env::temp_dir).join("agentscope-remote")
}

pub fn shot(path: &str, size: (u32, u32), ppp: f32, scene: Option<String>) -> Result<(), String> {
    let ctx = egui::Context::default();
    crate::setup_ctx(&ctx);
    let mut app = App::new(ctx.clone(), true);
    let screen = Rect::from_min_size(Pos2::ZERO, Vec2::new(size.0 as f32 / ppp, size.1 as f32 / ppp));
    let mut textures = HashMap::new();
    let mut last = None;
    for frame in 0..8 {
        if frame == 1 {
            if let Some(s) = &scene {
                app.demo_scene(s);
            }
        }
        let mut viewports = egui::ViewportIdMap::default();
        viewports.insert(ViewportId::ROOT, ViewportInfo { native_pixels_per_point: Some(ppp), focused: Some(true), ..Default::default() });
        let input = RawInput {
            viewport_id: ViewportId::ROOT,
            viewports,
            screen_rect: Some(screen),
            max_texture_side: Some(8192),
            time: Some(frame as f64 * 0.1),
            predicted_dt: 0.1,
            focused: true,
            ..Default::default()
        };
        let mut out = ctx.run_ui(input, |ui| app.draw(ui));
        apply(&mut textures, &mut out.textures_delta);
        last = Some(ctx.tessellate(out.shapes, out.pixels_per_point));
    }
    let prims = last.unwrap_or_default();
    let (w, h) = (size.0 as usize, size.1 as usize);
    let buf = raster(&prims, &textures, ppp, w, h, crate::theme::BG);
    let mut data = Vec::with_capacity(w * h * 3);
    for p in buf {
        for c in p {
            data.push((c.clamp(0.0, 1.0) * 255.0).round() as u8);
        }
    }
    let file = std::fs::File::create(path).map_err(|e| e.to_string())?;
    let mut enc = png::Encoder::new(std::io::BufWriter::new(file), size.0, size.1);
    enc.set_color(png::ColorType::Rgb);
    enc.set_depth(png::BitDepth::Eight);
    let mut wr = enc.write_header().map_err(|e| e.to_string())?;
    wr.write_image_data(&data).map_err(|e| e.to_string())?;
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn mirror_root_env_override_and_default() {
        // Ein einziger Test (statt zwei), weil beide Zweige dieselbe Umgebungsvariable anfassen und
        // parallele Tests sich sonst gegenseitig den Wert wegnehmen würden.
        std::env::set_var("COPI_STATE_MIRROR_DIR", "/tmp/spiegel-x");
        assert_eq!(state_mirror_root(), std::path::PathBuf::from("/tmp/spiegel-x"));
        std::env::remove_var("COPI_STATE_MIRROR_DIR");
        // Ohne Umlenkung liegt der Spiegel unter `<cache>/copi/agentscope-remote` – genau dort,
        // wo `agentscope.model.MIRROR_ROOT` liest.
        let p = state_mirror_root();
        assert!(p.ends_with("copi/agentscope-remote"), "unerwarteter Spiegelort: {}", p.display());
    }
}

//! Integrationstest des Hub-Transports gegen einen echten `pi-hub` (Mock-Harness).
//! Übersprungen, wenn Node oder der Hub fehlen (`PI_HUB_DIR`, Standard `~/Work/pi-hub`).
use pi_backend::instances::*;
use std::process::{Child, Command, Stdio};
use std::sync::{Arc, Mutex};
use std::time::Duration;

struct Hub(Child);
impl Drop for Hub {
    fn drop(&mut self) {
        let _ = self.0.kill();
        let _ = self.0.wait();
    }
}

fn start(port: u16, state: &std::path::Path, root: &std::path::Path) -> Option<Hub> {
    let dir = std::env::var("PI_HUB_DIR").ok().or_else(|| std::env::var("HOME").ok().map(|h| format!("{h}/Work/pi-hub")))?;
    if !std::path::Path::new(&dir).join("server.mjs").exists() {
        return None;
    }
    let c = Command::new("node")
        .arg("server.mjs")
        .current_dir(&dir)
        .env("HUB_PORT", port.to_string())
        .env("HUB_TOKEN", "t0k")
        .env("HUB_ROOTS", root)
        .env("HUB_STATE", state)
        .env("PI_SESSIONS_DIR", root.join("sess"))
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .spawn()
        .ok()?;
    let h = Hub(c);
    for _ in 0..60 {
        if std::net::TcpStream::connect(("127.0.0.1", port)).is_ok() {
            return Some(h);
        }
        std::thread::sleep(Duration::from_millis(100));
    }
    None
}

fn wait(v: &Arc<Mutex<Vec<Tagged>>>, f: impl Fn(&Tagged) -> bool) -> bool {
    for _ in 0..120 {
        if v.lock().unwrap().iter().any(&f) {
            return true;
        }
        std::thread::sleep(Duration::from_millis(50));
    }
    false
}

#[test]
fn hub_transport_end_to_end() {
    let tmp = std::env::temp_dir().join(format!("pi-backend-hub-{}", std::process::id()));
    std::fs::create_dir_all(tmp.join("proj")).unwrap();
    let port = 18900 + (std::process::id() % 500) as u16;
    let Some(hub) = start(port, &tmp.join("state.json"), &tmp) else {
        eprintln!("pi-hub nicht verfügbar – übersprungen");
        return;
    };
    let url = format!("http://127.0.0.1:{port}");

    // Falsches Token wird klar gemeldet.
    let bad = HubInstances::new("h", "Hub", &url, "falsch");
    assert!(bad.list().unwrap_err().contains("401"), "Token-Fehler muss sichtbar sein");

    let be = HubInstances::new("h", "Hub", &url, "t0k");
    assert!(be.is_remote());
    let root = be.files().dirs(None).unwrap();
    assert!(root.dirs.iter().any(|d| d == "proj"));
    assert!(be.files().dirs(Some("/")).is_err(), "Sandbox muss greifen");

    // Remote-Sessions: Liste mit cwd/Titel, Löschen nur im Session-Ordner.
    let sdir = tmp.join("sess").join("p");
    std::fs::create_dir_all(&sdir).unwrap();
    let sf = sdir.join("a.jsonl");
    let cwd = std::fs::canonicalize(tmp.join("proj")).unwrap().to_string_lossy().to_string();
    std::fs::write(&sf, format!("{{\"type\":\"session\",\"cwd\":\"{cwd}\"}}\n{{\"type\":\"message\",\"message\":{{\"role\":\"user\",\"content\":\"Remote-Titel\"}}}}\n")).unwrap();
    let ss = be.files().sessions().unwrap();
    assert_eq!(ss.len(), 1);
    assert_eq!((ss[0].cwd.as_str(), ss[0].title.as_str()), (cwd.as_str(), "Remote-Titel"));
    assert!(be.files().delete_session("/etc/passwd").unwrap_err().contains("403"));
    assert!(bad.files().delete_session(&ss[0].path).unwrap_err().contains("401"));
    be.files().delete_session(&ss[0].path).unwrap();
    assert!(!sf.exists() && be.files().sessions().unwrap().is_empty());

    // Remote-Session öffnen (copi/pi-lite: create mit `session`): außerhalb → 403;
    // offen in einer Instanz → Löschen 409; nach dem Entfernen der Instanz löschbar.
    let outside = Spec { harness: Some("mock".into()), cwd: cwd.clone(), session: Some("/etc/passwd".into()), ..Default::default() };
    assert!(be.create(&outside).unwrap_err().contains("403"));
    std::fs::write(&sf, "{\"type\":\"session\"}\n").unwrap();
    let sp = std::fs::canonicalize(&sf).unwrap().to_string_lossy().to_string();
    let open = be.create(&Spec { harness: Some("mock".into()), cwd: cwd.clone(), session: Some(sp.clone()), ..Default::default() }).unwrap();
    assert_eq!(open.session.as_deref(), Some(sp.as_str()));
    assert!(be.files().delete_session(&sp).unwrap_err().contains("409"));
    assert!(be.files().rename_session(&sp, "X").unwrap_err().contains("409"), "offene Session nicht umbenennen");
    assert!(be.files().rename_session("/etc/passwd", "X").unwrap_err().contains("403"));
    assert!(bad.files().rename_session(&sp, "X").unwrap_err().contains("401"));
    be.remove(&open.id).unwrap();
    be.files().delete_session(&sp).unwrap();

    let ev: Arc<Mutex<Vec<Tagged>>> = Default::default();
    let e2 = ev.clone();
    let sink: EvSink = Arc::new(move |t| e2.lock().unwrap().push(t));
    let _w = be.watch(sink.clone()).unwrap();
    let inst = be.create(&Spec { harness: Some("mock".into()), cwd: root.path.clone() + "/proj", ..Default::default() }).unwrap();
    assert!(wait(&ev, |t| t.inst == inst.id && matches!(t.ev, pi_backend::instances::Ev::Info(_))));

    let _sub = be.subscribe(&inst.id, sink.clone()).unwrap();
    assert!(wait(&ev, |t| t.inst == inst.id && t.ev == Ev::Live));
    be.harness(&inst.id).unwrap().send(&serde_json::json!({"type":"prompt","message":"Hallo"})).unwrap();
    assert!(wait(&ev, |t| t.inst == inst.id && matches!(&t.ev, Ev::Line(l) if l.contains("agent_settled"))));
    let settled = ev.lock().unwrap().iter().filter(|t| matches!(&t.ev, Ev::Line(l) if l.contains("agent_settled"))).count();
    assert_eq!(settled, 1);
    assert!(be.restart(&inst.id).is_err(), "laufende Instanz nicht neu startbar");

    // Zweites Abonnement = später Teilnehmer: bekommt Verlauf, dann Live; keine Doppelungen im ersten.
    let ev2: Arc<Mutex<Vec<Tagged>>> = Default::default();
    let e3 = ev2.clone();
    let _s2 = be.subscribe(&inst.id, Arc::new(move |t| e3.lock().unwrap().push(t))).unwrap();
    assert!(wait(&ev2, |t| t.ev == Ev::Live));
    let got = ev2.lock().unwrap().clone();
    let live = got.iter().position(|t| t.ev == Ev::Live).unwrap();
    assert!(got[..live].iter().any(|t| matches!(&t.ev, Ev::Line(l) if l.contains("agent_settled"))), "Verlauf vor Live");

    // Hub-Neustart: Registry bringt die Instanz zurück, Stream baut sich selbst wieder auf.
    drop(hub);
    assert!(wait(&ev, |t| t.ev == Ev::Link(false)), "Verbindungsabbruch wird gemeldet");
    let _hub2 = start(port, &tmp.join("state.json"), &tmp).expect("Hub-Neustart");
    assert_eq!(be.list().unwrap().len(), 1);
    assert_eq!(be.list().unwrap()[0].id, inst.id);
    ev.lock().unwrap().clear();
    assert!(wait(&ev, |t| t.ev == Ev::Link(true)), "Wiederaufbau");

    be.remove(&inst.id).unwrap();
    assert!(wait(&ev, |t| t.inst == inst.id && t.ev == Ev::Gone));
    assert!(be.list().unwrap().is_empty());
    let _ = std::fs::remove_dir_all(&tmp);
}

// Smoke-Test: startet den Hub auf einem freien Port mit Mock-Harness und prüft den Ablauf.
import { spawn } from 'node:child_process';
import assert from 'node:assert/strict';
import fs from 'node:fs'; import os from 'node:os'; import path from 'node:path';

const PORT = 18000 + Math.floor(Math.random() * 1000), TOKEN = 'testtoken';
const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'hub-'));
fs.mkdirSync(path.join(tmp, 'proj'));
const hub = spawn('node', ['server.mjs'], { env: { ...process.env, HUB_PORT: PORT, HUB_TOKEN: TOKEN, HUB_ROOTS: tmp, HUB_STATE: path.join(tmp, 'state.json'), PI_SESSIONS_DIR: path.join(tmp, 'sess'), HUB_PI_BIN: path.resolve('test/fake-pi.mjs') }, stdio: 'pipe' });
const base = `http://127.0.0.1:${PORT}`;
const H = { authorization: 'Bearer ' + TOKEN, 'content-type': 'application/json' };
const call = (p, o = {}) => fetch(base + '/api/' + p, { ...o, headers: { ...H, ...(o.headers || {}) } });
let fail = 0;
const t = async (name, fn) => { try { await fn(); console.log('ok  ', name); } catch (e) { fail++; console.log('FAIL', name, '\n    ', e.message); } };

async function sse(url, until, since = 0, ms = 8000) {
  const ac = new AbortController(); const out = [];
  const r = await fetch(url, { signal: ac.signal, headers: { ...H, 'last-event-id': String(since) } });
  const dec = new TextDecoder(); let buf = '';
  const timer = setTimeout(() => ac.abort(), ms);
  try {
    for await (const chunk of r.body) {
      buf += dec.decode(chunk, { stream: true }); let i;
      while ((i = buf.indexOf('\n\n')) >= 0) {
        const block = buf.slice(0, i); buf = buf.slice(i + 2);
        const d = block.split('\n').find(l => l.startsWith('data: ')); if (!d) continue;
        out.push(JSON.parse(d.slice(6))); if (until(out)) { ac.abort(); return out; }
      }
    }
  } catch (e) { if (e.name !== 'AbortError') throw e; } finally { clearTimeout(timer); }
  return out;
}

try {
  for (let i = 0; i < 50; i++) { try { await fetch(base + '/api/ping'); break; } catch { await new Promise(r => setTimeout(r, 100)); } }

  await t('ohne Token: 401', async () => assert.equal((await fetch(base + '/api/ping')).status, 401));
