  await t('Ordnerliste liegt in Wurzel', async () => { const d = await (await call('dirs')).json(); assert.ok(d.dirs.includes('proj')); assert.equal(d.parent, null); });
  await t('Sandbox: Pfad außerhalb → 403', async () => assert.equal((await call('dirs?path=/etc')).status, 403));
  await t('Sandbox: ../ Ausbruch → 403', async () => assert.equal((await call('dirs?path=' + encodeURIComponent(tmp + '/proj/../..'))).status, 403));
