  await t('Session außerhalb des Session-Ordners → 403', async () => assert.equal((await call('instances', { method: 'POST', body: JSON.stringify({ harness: 'mock', cwd: tmp, session: '/etc/passwd' }) })).status, 403));
  await t('unbekannter Harness → 400', async () => assert.equal((await call('instances', { method: 'POST', body: JSON.stringify({ harness: 'x', cwd: tmp }) })).status, 400));

