  // Regression: Mock überschrieb eine mitgegebene Session (Remote-Öffnen aus copi/pi-lite) mit eigenem Pfad.
  await t('Instanz mit vorhandener Session behält den Pfad', async () => {
    const dir = path.join(tmp, 'sess', 'p2'); fs.mkdirSync(dir, { recursive: true });
    const f = path.join(dir, 'open.jsonl'); fs.writeFileSync(f, JSON.stringify({ type: 'session' }) + '\n');
    const r = await call('instances', { method: 'POST', body: JSON.stringify({ harness: 'mock', cwd: path.join(tmp, 'proj'), session: f }) });
    assert.equal(r.status, 201); const i = await r.json();
    await new Promise(r => setTimeout(r, 150));
    const now = (await (await call('instances')).json()).find(x => x.id === i.id);
    assert.equal(now.session, f);
    assert.equal((await call('sessions?path=' + encodeURIComponent(f), { method: 'DELETE' })).status, 409);
    assert.equal((await call('instances/' + i.id, { method: 'DELETE' })).status, 200);
    fs.rmSync(f);
  });

  let inst;
  await t('Instanz anlegen (mock)', async () => { const r = await call('instances', { method: 'POST', body: JSON.stringify({ harness: 'mock', cwd: path.join(tmp, 'proj') }) }); assert.equal(r.status, 201); inst = await r.json(); assert.equal(inst.state, 'idle'); assert.equal(inst.name, 'proj'); });

  await t('Prompt → Streaming → agent_settled', async () => {
    const wait = sse(`${base}/api/instances/${inst.id}/events`, o => o.some(r => r.ev.type === 'agent_settled'));
    await new Promise(r => setTimeout(r, 150));
    assert.equal((await call(`instances/${inst.id}/rpc`, { method: 'POST', body: JSON.stringify({ type: 'prompt', id: 'p1', message: 'Hallo' }) })).status, 202);
    const evs = (await wait).map(r => r.ev);
    const text = evs.filter(e => e.type === 'message_update' && e.assistantMessageEvent.type === 'text_delta').map(e => e.assistantMessageEvent.delta).join('');
    assert.match(text, /Du hast gesagt: \*\*Hallo\*\*/);
    assert.ok(evs.some(e => e.type === 'tool_execution_start'));
  });

  await t('seq streng aufsteigend, Replay mit Last-Event-ID', async () => {
    const all = await sse(`${base}/api/instances/${inst.id}/events`, o => o.some(r => r.ev.type === 'agent_settled'));
    const seqs = all.map(r => r.seq); assert.deepEqual(seqs, [...seqs].sort((a, b) => a - b)); assert.equal(new Set(seqs).size, seqs.length);
    const mid = seqs[Math.floor(seqs.length / 2)];
    const rest = await sse(`${base}/api/instances/${inst.id}/events`, o => o.length >= seqs.filter(s => s > mid).length, mid);
