    await new Promise(r => setTimeout(r, 600));
    const r = await fetch(`http://127.0.0.1:${p2}/api/instances`, { method: 'POST', headers: H, body: JSON.stringify({ harness: 'pi', cwd: tmp }) });
    assert.equal(r.status, 201); await new Promise(r => setTimeout(r, 400));
    const l = await (await fetch(`http://127.0.0.1:${p2}/api/instances`, { headers: H })).json(); assert.equal(l[0].state, 'exited');
    const rs = await fetch(`http://127.0.0.1:${p2}/api/instances/${l[0].id}/restart`, { method: 'POST', headers: H });
    assert.equal(rs.status, 200);
    h2.kill();
  });

  await t('Neustart einer laufenden Instanz → 409', async () => assert.equal((await call(`instances/${inst.id}/restart`, { method: 'POST' })).status, 409));

  await t('Session-Datei wird aus get_state übernommen', async () => {
    const s = (await (await call('instances')).json())[0]; assert.match(s.session || '', /\.jsonl$/);
  });

  await t('Session einer laufenden Instanz löschen → 409', async () => {
    const s = (await (await call('instances')).json())[0];
