  await t('Registry: Instanzen überleben Hub-Neustart', async () => {
    const p3 = PORT + 2, state = path.join(tmp, 'state3.json');
    const env = { ...process.env, HUB_PORT: p3, HUB_TOKEN: TOKEN, HUB_ROOTS: tmp, HUB_STATE: state, PI_SESSIONS_DIR: path.join(tmp, 'sess') };
    const up = async () => { for (let i = 0; i < 50; i++) { try { await fetch(`http://127.0.0.1:${p3}/api/ping`); return; } catch { await new Promise(r => setTimeout(r, 100)); } } };
    let h3 = spawn('node', ['server.mjs'], { env, stdio: 'pipe' }); await up();
    const mk = await (await fetch(`http://127.0.0.1:${p3}/api/instances`, { method: 'POST', headers: H, body: JSON.stringify({ harness: 'mock', cwd: tmp, name: 'bleibt' }) })).json();
    await new Promise(r => setTimeout(r, 200)); h3.kill('SIGTERM'); await new Promise(r => h3.on('exit', r));
    assert.ok(fs.existsSync(state));
    h3 = spawn('node', ['server.mjs'], { env, stdio: 'pipe' }); await up();
    try {
      const l = await (await fetch(`http://127.0.0.1:${p3}/api/instances`, { headers: H })).json();
      assert.equal(l.length, 1); assert.equal(l[0].id, mk.id); assert.equal(l[0].name, 'bleibt');
      assert.equal((await fetch(`http://127.0.0.1:${p3}/api/instances/${mk.id}`, { method: 'DELETE', headers: H })).status, 200);
      assert.equal(JSON.parse(fs.readFileSync(state, 'utf8')).instances.length, 0);
    } finally { h3.kill(); }
  });

  await t('Instanz löschen', async () => { assert.equal((await call('instances/' + inst.id, { method: 'DELETE' })).status, 200); assert.equal((await (await call('instances')).json()).length, 0); });
} finally { hub.kill(); fs.rmSync(tmp, { recursive: true, force: true }); }
console.log(fail ? `\n${fail} Test(s) fehlgeschlagen` : '\nalle Tests bestanden'); process.exit(fail ? 1 : 0);

    Ok(())
}

