        _ => {}
    }
    if let Err(e) = check_args(&args) {
        eprintln!("{}: {e}. Kein Fenster geöffnet.\nVermutlich ruft ein Desktop-Eintrag {0} als Terminal oder Browser auf; siehe scripts/check-desktop.sh.", app_name());
